const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const receipts = [];
  const service = new PaymentService(ledger, {
    acknowledge: async receipt => { receipts.push(receipt); }
  });
  const original = await service.pay('shop', 'sale', 123);
  assert.deepEqual(original, { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
  assert.equal(ledger.entries.length, 1);
  assert.equal(receipts.length, 1);
  assert.strictEqual(await service.pay('shop', 'sale', 123), original);
  await assert.rejects(service.pay('shop', 'sale', 124), { message: 'key conflict' });
  assert.equal(ledger.entries.length, 1);
  assert.equal(receipts.length, 2);

  // Tenant/key pairs, not keys alone or delimiter-joined strings, define identity.
  await service.pay('other', 'sale', 124);
  await service.pay('a:b', 'c', 1);
  await service.pay('a', 'b:c', 2);
  assert.equal(ledger.entries.length, 4);

  const concurrentLedger = new Ledger();
  let release;
  const pending = new Promise(resolve => { release = resolve; });
  const concurrentService = new PaymentService(concurrentLedger, {
    acknowledge: async () => pending
  });
  const first = concurrentService.pay('shop', 'concurrent', 10);
  const second = concurrentService.pay('shop', 'concurrent', 10);
  await assert.rejects(concurrentService.pay('shop', 'concurrent', 11), { message: 'key conflict' });
  assert.equal(concurrentLedger.entries.length, 1);
  release();
  const [a, b] = await Promise.all([first, second]);
  assert.strictEqual(a, b);
  assert.strictEqual(await concurrentLedger.apply('shop', 'concurrent', 10), a);
  await assert.rejects(concurrentLedger.apply('shop', 'concurrent', 11), { message: 'key conflict' });

  // Validation must precede even the first ledger or transport call.
  const noActions = new PaymentService({
    apply: async () => assert.fail('ledger called for invalid input')
  }, { acknowledge: async () => assert.fail('transport called for invalid input') });
  const invalid = [
    ['', 'key', 1, 3], ['tenant', '', 1, 3],
    [null, 'key', 1, 3], ['tenant', 1, 1, 3],
    ...[0, -1, 0.5, NaN, Infinity, '1'].map(cents => ['tenant', 'key', cents, 3]),
    ...[0, -1, 6, 1.5, NaN, Infinity, '3', null].map(attempts => ['tenant', 'key', 1, attempts])
  ];
  for (const args of invalid) {
    await assert.rejects(noActions.pay(...args), { message: 'invalid payment' });
  }
  await assert.rejects(concurrentLedger.apply('', 'key', 1), { message: 'invalid payment' });
  assert.equal(concurrentLedger.entries.length, 1);

  for (const attempts of [1, 3, 5]) {
    const retryLedger = new Ledger();
    let applyCalls = 0;
    const apply = retryLedger.apply.bind(retryLedger);
    retryLedger.apply = async (...args) => { applyCalls++; return apply(...args); };
    const seen = [];
    const errors = Array.from({ length: attempts }, (_, n) => new Transient(`failure ${n}`));
    const retryService = new PaymentService(retryLedger, {
      acknowledge: async receipt => {
        seen.push(receipt);
        throw errors[seen.length - 1];
      }
    });
    await assert.rejects(retryService.pay('shop', 'retry', 5, attempts), error => error === errors.at(-1));
    assert.equal(seen.length, attempts);
    assert.equal(applyCalls, 1);
    assert.equal(retryLedger.entries.length, 1);
    for (const receipt of seen) assert.strictEqual(receipt, retryLedger.entries[0]);
  }

  const successLedger = new Ledger();
  const seen = [];
  const successService = new PaymentService(successLedger, {
    acknowledge: async receipt => {
      seen.push(receipt);
      if (seen.length < 3) throw new Transient('try again');
    }
  });
  const success = await successService.pay('shop', 'success', 7);
  assert.equal(seen.length, 3);
  assert.equal(successLedger.entries.length, 1);
  for (const receipt of seen) assert.strictEqual(receipt, success);

  const fatal = new Error('fatal');
  let calls = 0;
  const fatalService = new PaymentService(new Ledger(), {
    acknowledge: async () => { calls++; throw fatal; }
  });
  await assert.rejects(fatalService.pay('shop', 'fatal', 1), error => error === fatal);
  assert.equal(calls, 1);
  calls = 0;
  const fatalLedgerService = new PaymentService({
    apply: async () => { calls++; throw fatal; }
  }, { acknowledge: async () => assert.fail('acknowledged failed debit') });
  await assert.rejects(fatalLedgerService.pay('shop', 'fatal', 1), error => error === fatal);
  assert.equal(calls, 1);
}

module.exports = main();
EOF
